posts.body:
Create a new plugin file with any name, and paste this:
Code:
/*:
 * @target MZ
 */
Sprite_Actor.prototype.setHome = function(x, y) {
    if (this.deltaX()) {
        x += this.deltaX();
    }
    if (this.deltaY()) {
        y += this.deltaY();
    }
    Sprite_Battler.prototype.setHome.call(this, x, y);
}
Sprite_Actor.prototype.deltaX = function() {
    return this.notetags() && 'Delta X' in this.notetags()
        ? Number(this.notetags()['Delta X'])
        : undefined;
}
Sprite_Actor.prototype.deltaY = function() {
    return this.notetags() && 'Delta Y' in this.notetags()
        ? Number(this.notetags()['Delta Y'])
        : undefined;
}
Sprite_Actor.prototype.notetags = function() {
    return this._actor && this._actor.actor()
        ? this._actor.actor().meta
        : undefined;
}
Now, you can use the Notetags <Delta X: -50> and <Delta Y: 20> for example.
I can also change it for class Notetags when that's more useful for you.
